 internal void LoadFile(){ReleaseMedia();path=files[index];title.Text=Path.GetFileName(path)+(files.Length>1?"    "+(index+1)+" / "+files.Length:"");location.Text="Show in folder · "+path;location.LinkBehavior=LinkBehavior.AlwaysUnderline;details.Text="Space / Esc: close · arrows: selected files";
  try{var info=new FileInfo(path);if(!info.Exists)throw new IOException("This file was moved or removed.");string ext=info.Extension.ToLowerInvariant();
   if(new[]{".png",".jpg",".jpeg",".bmp",".gif",".tif",".tiff",".ico"}.Contains(ext)){if(info.Length>50*1024*1024)throw new IOException("This image is over the 50 MB preview limit. Use Open in default app.");imageBytes=new MemoryStream(ReadBounded(path,50*1024*1024));image=Image.FromStream(imageBytes);if((long)image.Width*image.Height>60000000)throw new IOException("This image is too large for a quick preview. Use Open in default app.");picture=new PictureBox{Dock=DockStyle.Fill,Image=image,SizeMode=PictureBoxSizeMode.Zoom};imageScroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};imageScroll.Controls.Add(picture);content.Controls.Add(imageScroll);var row=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=42};foreach(var text in new[]{"Fit","1:1","Copy image"}){var b=new Button{Text=text,AutoSize=true};string action=text;b.Click+=(s,e)=>{if(action=="Copy image"){try{using(var copy=new Bitmap(image))Clipboard.SetImage(copy);}catch(Exception error){details.Text=error.Message;}}else{zoom=action=="Fit"?0:1;picture.Dock=zoom==0?DockStyle.Fill:DockStyle.None;picture.SizeMode=zoom==0?PictureBoxSizeMode.Zoom:PictureBoxSizeMode.Normal;if(zoom!=0)picture.Size=image.Size;}};row.Controls.Add(b);}content.Controls.Add(row);details.Text=image.Width+" × "+image.Height+" · "+SizeText(info.Length)+" · Space / Esc closes";}
