   else content.Controls.Add(new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,Text=info.Name+"\n\n"+SizeText(info.Length)+" · "+(ext.Length>0?ext:"File")+"\nModified "+info.LastWriteTime.ToString("g")+"\n\nNo inline preview for this format yet.\nChoose Open in default app to view it."});
  }catch(Exception error){ReleaseMedia();content.Controls.Add(new Label{Dock=DockStyle.Fill,Text=error.Message,TextAlign=ContentAlignment.MiddleCenter});}
  CompanionPalette.Apply(this,PreviewProgram.Theme);
