 internal static byte[] ReadBounded(string file,int limit){using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(stream.Length>limit)throw new IOException("This file is too large for a quick preview. Use Open in default app.");using(var memory=new MemoryStream()){byte[] buffer=new byte[8192];int count;while((count=stream.Read(buffer,0,Math.Min(buffer.Length,limit-(int)memory.Length+1)))>0){if(memory.Length+count>limit)throw new IOException("This file grew beyond the preview limit.");memory.Write(buffer,0,count);}return memory.ToArray();}}}
