  seeking=new PreviewSeeking(()=>media.Pause(),()=>media.Play(),v=>media.Position=TimeSpan.FromMilliseconds(Math.Max(0,Math.Min(media.NaturalDuration.TimeSpan.TotalMilliseconds-1,v*media.NaturalDuration.TimeSpan.TotalMilliseconds))),m=>media.IsMuted=userMute||m);
  seekTimer=new System.Windows.Forms.Timer{Interval=180};seekTimer.Tick+=(s,e)=>{if(seeking.Dragging)return;if(!settling){settling=seeking.Commit();if(!settling)seekTimer.Stop();}else{seekTimer.Stop();settling=false;seeking.Finish();}};
  slider.MouseDown+=(s,e)=>{if(e.Button==MouseButtons.Left&&media.NaturalDuration.HasTimeSpan){seekTimer.Stop();settling=false;seeking.Begin();seeking.Request(slider.Value/1000.0);play.Text=seeking.ButtonText;}};slider.MouseCaptureChanged+=(s,e)=>{if(!slider.Capture&&seeking.Dragging){seeking.Release();seekTimer.Start();}};slider.ValueChanged+=(s,e)=>{if(updating||!media.NaturalDuration.HasTimeSpan)return;seekTimer.Stop();settling=false;seeking.Request(slider.Value/1000.0);play.Text=seeking.ButtonText;if(!seeking.Dragging)seekTimer.Start();};play.Click+=(s,e)=>{if(!media.NaturalDuration.HasTimeSpan)return;bool replay=seeking.Ended;seeking.Toggle();if(replay){settling=false;seekTimer.Start();}play.Text=seeking.ButtonText;};mute.CheckedChanged+=(s,e)=>{userMute=mute.Checked;media.IsMuted=userMute||seeking.Pending;};
