 protected override bool ProcessCmdKey(ref Message msg,Keys key){if(key==Keys.Escape||key==Keys.Space){Close();return true;}if(files.Length>1&&(key==Keys.Left||key==Keys.Up)){Navigate(-1);return true;}if(files.Length>1&&(key==Keys.Right||key==Keys.Down)){Navigate(1);return true;}if(key==Keys.Enter){try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception e){details.Text=e.Message;}return true;}return base.ProcessCmdKey(ref msg,key);}
